data = {}
for i, theme in enumerate(themes_de):
    tasks = []
    # Generate 25 MCQ
    q_bank = get_questions_de(i)
    for j in range(25):
        q_text, opts, corr = q_bank[j % len(q_bank)]
        tasks.append({
            "type": "mcq",
            "question": q_text,
            "options": opts,
            "correct": corr
        })
    # Generate 10 Typing
    t_words = get_typing_words_de(i)
    for k in range(10):
        word = t_words[k % len(t_words)]
        tasks.append({
            "type": "typing",
            "question": f"Gépeld be: {word}",
            "answer": word
        })
    # Note: user asked for "Gépeld be: ..." in typing? 
    # Wait, the requirement says "Language: German". 
    # "Gépeld be" is Hungarian for "Type in". 
    # I should use "Tippe ein: " or just the word.
    for task in tasks:
        if task["type"] == "typing":
            task["question"] = f"Tippe ein: {task['answer']}"

    data[str(i+1)] = {
        "theme": theme,
        "tasks": tasks
    }

